146	static void pulse_encoder_timeout_handle(void *parameter)
147	{
148	    static int32_t last_count = 0;
149	    rt_err_t result;
150	    struct rt_encoder_configuration config_count;
151	    config_count.get_count = 0;
152	    result =
153	        rt_device_control((struct rt_device *)s_encoder_device,
154	                          PULSE_ENCODER_CMD_GET_COUNT, (void *)&config_count);
155	    if (result != RT_EOK)
156	    {
157	        LOG_E("Failed to get encoder count\n");
158	        return;
159	    }
160	
161	    int32_t current_count = config_count.get_count;
162	    int32_t delta_count = current_count - last_count;
163	    last_count = current_count;
164	    // delta_count
165	    // 是以4为单位的增量，不能被4整除不算一次脉冲，需要先算出有多少增量
166	    // 注意正数是顺时针转动，负数是逆时针转动
167	    if (delta_count % 4 != 0)
168	    {
169	        LOG_W("Encoder count is not a multiple of 4, delta_count: %d\n",
170	              delta_count);
171	        return;
172	    }
173	    int32_t pulses = delta_count / 4; // 每次脉冲是4个单位
174	    if (pulses != 0)
175	    {
176	        LOG_I("Pulse encoder count: %d\n", pulses);
177	        int current_volume =
178	            audio_server_get_private_volume(AUDIO_TYPE_LOCAL_MUSIC);
179	        int new_volume = current_volume + pulses;
180	        if (new_volume < 0)
181	        {
182	            new_volume = 0; // 最小音量为0
183	        }
184	        else if (new_volume > 15)
185	        {
186	            new_volume = 15; // 最大音量为15
187	        }
188	
189	        audio_server_set_private_volume(AUDIO_TYPE_LOCAL_MUSIC, new_volume);
190	    }
191	}
