441	static int bt_app_interface_event_handle(uint16_t type, uint16_t event_id,
442	                                         uint8_t *data, uint16_t data_len)
443	{
444	    if (type == BT_NOTIFY_COMMON)
445	    {
446	        int pan_conn = 0;
447	
448	        switch (event_id)
449	        {
450	        case BT_NOTIFY_COMMON_BT_STACK_READY:
451	        {
452	            rt_mb_send(g_bt_app_mb, BT_APP_READY);
453	        }
454	        break;
455	        case BT_NOTIFY_COMMON_ACL_CONNECTED:
456	        {
457	            LOG_I("BT_NOTIFY_COMMON_ACL_CONNECTED\n");
458				// 清除蓝牙主动断开标志位
459	            Initiate_disconnection_flag = 0;
460	
461	        }
462	        break;
463	        case BT_NOTIFY_COMMON_ACL_DISCONNECTED:
464	        {
465	            bt_notify_device_base_info_t *info =
466	                (bt_notify_device_base_info_t *)data;
467	            LOG_I("disconnected(0x%.2x:%.2x:%.2x:%.2x:%.2x:%.2x) res %d",
468	                  info->mac.addr[5], info->mac.addr[4], info->mac.addr[3],
469	                  info->mac.addr[2], info->mac.addr[1], info->mac.addr[0],
470	                  info->res);
471	            g_bt_app_env.bt_connected = FALSE;
472	            xiaozhi_ui_chat_output("蓝牙断开连接");
473	            xiaozhi_ui_standby_chat_output("蓝牙断开连接");//待机画面
474	            lv_obj_t *now_screen = lv_screen_active();
475	            if (now_screen != standby_screen && now_screen != sleep_screen && now_screen != shutdown_screen)
476	                {
477	                    ui_swith_to_standby_screen();
478	                }
479	            //  memset(&g_bt_app_env.bd_addr, 0xFF,
480	            //  sizeof(g_bt_app_env.bd_addr));
481	                 if (info->res == BT_NOTIFY_COMMON_SCO_DISCONNECTED) 
482	                {
483	                
484	                    LOG_I("Phone actively disconnected, prepare to enter sleep mode after 30 seconds");
485	                    rt_mb_send(g_bt_app_mb, BT_APP_PHONE_DISCONNECTED);
486	                }
487	                else 
488	                {
489	                    LOG_I("Abnormal disconnection, start reconnect attempts");
490	                    rt_mb_send(g_bt_app_mb, BT_APP_ABNORMAL_DISCONNECT);
491	                }
492	            
493	            if (g_bt_app_env.pan_connect_timer)
494	                rt_timer_stop(g_bt_app_env.pan_connect_timer);
495	        }
496	        break;
497	        case BT_NOTIFY_COMMON_ENCRYPTION:
498	        {
499	            bt_notify_device_mac_t *mac = (bt_notify_device_mac_t *)data;
500	            LOG_I("Encryption competed");
501	            g_bt_app_env.bd_addr = *mac;
502	            pan_conn = 1;
503	        }
504	        break;
505	        case BT_NOTIFY_COMMON_PAIR_IND:
506	        {
507	            bt_notify_device_base_info_t *info =
508	                (bt_notify_device_base_info_t *)data;
509	            LOG_I("Pairing completed %d", info->res);
510	            if (info->res == BTS2_SUCC)
511	            {
512	                g_bt_app_env.bd_addr = info->mac;
513	                pan_conn = 1;
514	            }
515	        }
516	        break;
517	        case BT_NOTIFY_COMMON_KEY_MISSING:
518	        {
519	            bt_notify_device_base_info_t *info =
520	                (bt_notify_device_base_info_t *)data;
521	            LOG_I("Key missing %d", info->res);
522	            memset(&g_bt_app_env.bd_addr, 0xFF, sizeof(g_bt_app_env.bd_addr));
523	            bt_cm_delete_bonded_devs_and_linkkey(info->mac.addr);
524	        }
525	        break;
526	        default:
527	            break;
528	        }
529	
530	        if (pan_conn)
531	        {
532	            LOG_I("bd addr 0x%.2x:%.2x:%.2x:%.2x:%.2x:%.2x\n",
533	                  g_bt_app_env.bd_addr.addr[5], g_bt_app_env.bd_addr.addr[4],
534	                  g_bt_app_env.bd_addr.addr[3], g_bt_app_env.bd_addr.addr[2],
535	                  g_bt_app_env.bd_addr.addr[1], g_bt_app_env.bd_addr.addr[0]);
536	            g_bt_app_env.bt_connected = TRUE;
537	            // Trigger PAN connection after PAN_TIMER_MS period to avoid SDP
538	            // confliction.
539	            if (!g_bt_app_env.pan_connect_timer)
540	                g_bt_app_env.pan_connect_timer = rt_timer_create(
541	                    "connect_pan", bt_app_connect_pan_timeout_handle,
542	                    (void *)&g_bt_app_env,
543	                    rt_tick_from_millisecond(PAN_TIMER_MS),
544	                    RT_TIMER_FLAG_SOFT_TIMER);
545	            else
546	                rt_timer_stop(g_bt_app_env.pan_connect_timer);
547	            rt_timer_start(g_bt_app_env.pan_connect_timer);
548	        }
549	    }
550	    else if (type == BT_NOTIFY_PAN)
551	    {
552	        switch (event_id)
553	        {
554	        case BT_NOTIFY_PAN_PROFILE_CONNECTED:
555	        {
556	            xiaozhi_ui_chat_output("PAN连接成功");
557	            xiaozhi_ui_standby_chat_output("PAN连接成功");//待机画面
558	            xiaozhi_ui_update_ble("open");
559	            LOG_I("pan connect successed \n");
560	            if ((g_bt_app_env.pan_connect_timer))
561	            {
562	                rt_timer_stop(g_bt_app_env.pan_connect_timer);
563	            }
564	            rt_mb_send(g_bt_app_mb, BT_APP_CONNECT_PAN_SUCCESS);
565	            g_pan_connected = TRUE; // 更新PAN连接状态
566	            
567	        }
568	        break;
569	        case BT_NOTIFY_PAN_PROFILE_DISCONNECTED:
570	        {
571	            xiaozhi_ui_chat_status("PAN断开...");
572	            xiaozhi_ui_chat_output("PAN断开,尝试唤醒键重新连接");
573	            xiaozhi_ui_standby_chat_output("PAN断开,尝试唤醒键重新连接");//待机画面
574	            xiaozhi_ui_update_ble("close");
575	            last_listen_tick = 0;
576	            LOG_I("pan disconnect with remote device\n");
577	            g_pan_connected = FALSE; // 更新PAN连接状态
578	            
579	            if (first_pan_connected ==
580	                FALSE) // Check if the pan has ever been connected
581	            {
582	                rt_mb_send(g_bt_app_mb, KEEP_FIRST_PAN_RECONNECT);
583	            }
584	        }
585	        break;
586	        default:
587	            break;
588	        }
589	    }
590	    else if (type == BT_NOTIFY_HID)
591	    {
592	        switch (event_id)
593	        {
594	        case BT_NOTIFY_HID_PROFILE_CONNECTED:
595	        {
596	            LOG_I("HID connected\n");
597	            if (!g_pan_connected)
598	            {
599	                if (g_bt_app_env.pan_connect_timer)
600	                {
601	                    rt_timer_stop(g_bt_app_env.pan_connect_timer);
602	                }
603	                bt_interface_conn_ext((char *)&g_bt_app_env.bd_addr,
604	                                      BT_PROFILE_PAN);
605	            }
606	        }
607	        break;
608	        case BT_NOTIFY_HID_PROFILE_DISCONNECTED:
609	        {
610	            LOG_I("HID disconnected\n");
611	        }
612	        break;
613	        default:
614	            break;
615	        }
616	    }
617	
618	    return 0;
619	}
